g=pd.DataFrame(geo);g.to_csv(O/'geographic_gate.csv',index=False);ratio=g[g.model=='weak_local'].set_index('region')[['rmse','mae']]/g[g.model=='reference'].set_index('region')[['rmse','mae']];gate=bool((ratio<=1.05).all().all()and(ratio.mean()<=1.01).all());dump(ratio.to_dict(),'geographic_ratios.json');out={'geographic_gate_pass':gate,'legacy_evaluated':False,'promote':False,'params':params,'decision_uses_development_checks':True}
