 m=ClusterWeightedOrientationForest(**params,seeds=(7,42,99)).fit(dev[cols],dev.count_2017_2021);test=df[df.eligible&(df.split=='test')];reference=joblib.load(mp);before=reference.predict(test[cols]);after=m.predict(test[cols]);bm=met(test.count_2017_2021,before,test[['cx','cy']]);am=met(test.count_2017_2021,after,test[['cx','cy']]);promote=am['rmse']<bm['rmse']and am['mae']<bm['mae']and am['p90_abs_error']<=bm['p90_abs_error']*1.02 and am['error_gt200_count']<=bm['error_gt200_count']and abs(am['moran_i'])<=abs(bm['moran_i']);out.update(legacy_evaluated=True,before=bm,after=am,promote=promote);pd.DataFrame({'grid_id':test.grid_id,'observed':test.count_2017_2021,'before':before,'after':after}).to_csv(O/'legacy_comparison.csv',index=False)
 if promote:joblib.dump(m,O/'candidate.joblib')
